-- The ledger is append-only for everyone, the owner included (INV-13; _db/billing.md 5). The runtime roles hold no
-- UPDATE or DELETE on it (ops/provision-roles.sql); this stops the owner and the migrations too. Only the referential
-- actions get through: an account deletion's cascade and an application deletion's SET NULL of application_id.
CREATE FUNCTION credit_ledger_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- pg_trigger_depth() is 1 for a plain statement and 2 or more inside a referential action.
  IF pg_trigger_depth() >= 2 THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    IF NEW.application_id IS NULL
       AND (NEW.id, NEW.user_id, NEW.delta, NEW.reason, NEW.stripe_invoice_id, NEW.note, NEW.created_at)
           IS NOT DISTINCT FROM
           (OLD.id, OLD.user_id, OLD.delta, OLD.reason, OLD.stripe_invoice_id, OLD.note, OLD.created_at)
    THEN RETURN NEW; END IF;
  END IF;
  RAISE EXCEPTION 'credit_ledger is append-only (% blocked)', TG_OP USING ERRCODE = '42501';
END $$;--> statement-breakpoint
CREATE TRIGGER credit_ledger_immutable_bud BEFORE UPDATE OR DELETE ON credit_ledger
  FOR EACH ROW EXECUTE FUNCTION credit_ledger_immutable();--> statement-breakpoint

-- Status guard version 1 (_db/applications.md 4.1, 5.3): only the legal transitions; nothing reaches submitting or
-- submitted from draft (INV-3), and only an extension claim is released back to approved. Versions 2 and 3 (the
-- draft_state and verification gates) and the late-confirmation rule need columns WP-42 adds.
CREATE FUNCTION applications_guard_status() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF (OLD.status::text, NEW.status::text) NOT IN (
       ('draft','approved'),      ('draft','withdrawn'),
       ('approved','submitting'), ('approved','submitted'), ('approved','failed'),
       ('approved','withdrawn'),  ('approved','draft'),
       ('submitting','submitted'),('submitting','failed'),  ('submitting','approved'),
       ('failed','approved'),     ('failed','submitted'),   ('failed','withdrawn')) THEN
    RAISE EXCEPTION 'illegal application transition % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514', CONSTRAINT = 'applications_status_guard';
  END IF;
  IF OLD.status = 'submitting' AND NEW.status = 'approved' AND NEW.channel IS DISTINCT FROM 'extension' THEN
    RAISE EXCEPTION 'only an extension claim can be released' USING ERRCODE = '23514', CONSTRAINT = 'applications_status_guard';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER applications_guard_status_bu BEFORE UPDATE OF status ON applications
  FOR EACH ROW EXECUTE FUNCTION applications_guard_status();--> statement-breakpoint

-- The transaction-local actor (02-database 3.2): set with set_config('kairos.actor', $1, true) by asActor() in
-- src/lib/actor.ts. 'user' is a request by the signed-in owner, 'ops' an operator repair; unset is a worker.
CREATE FUNCTION kairos_actor() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE AS $$ SELECT coalesce(current_setting('kairos.actor', true), '') $$;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION kairos_actor() TO PUBLIC;--> statement-breakpoint

-- facts_guard (_db/identity-profile.md 5.3, the truth lock's database backstop, INV-2): only a user action confirms,
-- unconfirms or edits a fact, or creates a confirmed or user-asserted one; an edit by the user makes the words theirs.
-- confirmed_at and updated_at are the trigger's. The source_span_hash and employment rules join with WP-17's columns.
CREATE FUNCTION facts_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  actor text    := kairos_actor();
  human boolean := kairos_actor() IN ('user', 'ops');
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF actor = 'user' AND NEW.asserted_by <> 'user' THEN
      RAISE EXCEPTION 'a user action can only create facts asserted by the user' USING ERRCODE = '23514', CONSTRAINT = 'facts_actor_required';
    ELSIF NOT human AND (NEW.asserted_by = 'user' OR NEW.confirmed) THEN
      RAISE EXCEPTION 'only a user action can create a confirmed or user-asserted fact' USING ERRCODE = '23514', CONSTRAINT = 'facts_actor_required';
    END IF;
    NEW.confirmed_at := CASE WHEN NEW.confirmed THEN coalesce(NEW.confirmed_at, now()) ELSE NULL END;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF NEW.user_id <> OLD.user_id THEN
    RAISE EXCEPTION 'facts.user_id is immutable' USING ERRCODE = '23514', CONSTRAINT = 'facts_user_immutable';
  END IF;
  IF NEW.asserted_by IS DISTINCT FROM OLD.asserted_by AND actor <> 'ops' THEN
    RAISE EXCEPTION 'asserted_by changes only through an edit by the owner' USING ERRCODE = '23514', CONSTRAINT = 'facts_actor_required';
  END IF;
  IF NEW.text IS DISTINCT FROM OLD.text OR NEW.kind IS DISTINCT FROM OLD.kind THEN
    IF NOT human THEN
      RAISE EXCEPTION 'only a user action can edit a fact' USING ERRCODE = '23514', CONSTRAINT = 'facts_actor_required';
    END IF;
    IF actor = 'user' THEN NEW.asserted_by := 'user'; END IF;
    IF OLD.confirmed AND NEW.confirmed THEN NEW.confirmed_at := now(); END IF;
  END IF;
  IF NEW.confirmed IS DISTINCT FROM OLD.confirmed THEN
    IF NOT human THEN
      RAISE EXCEPTION 'only a user action can confirm or unconfirm a fact' USING ERRCODE = '23514', CONSTRAINT = 'facts_actor_required';
    END IF;
    NEW.confirmed_at := CASE WHEN NEW.confirmed THEN now() ELSE NULL END;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER facts_guard_biu BEFORE INSERT OR UPDATE ON facts
  FOR EACH ROW EXECUTE FUNCTION facts_guard();
